window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[183]={"id":"183","numero":183,"titre":"Organisation de la médecine du travail","objectifs":[{"id":"183-1","rang":"B","rubrique":"Définition","titre":"Connaître l’organisation des services de santé au travail","contenu":"<p>Le <span class=\"kw-def\">Code du travail</span> impose à <strong>tout employeur ayant <span class=\"kw-chiffre\">≥ 1 salarié</span></strong> d’organiser ou d’adhérer à un <strong><span class=\"kw-def\">service de prévention et de santé au travail</span> (SPST)</strong>.</p>\n\n      <h4 class=\"kw-def\">Deux formes d’organisation</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">SPST autonomes</span></strong> : services propres à une entreprise (réservés aux <span class=\"kw-clinique\">grosses entreprises</span>).</li>\n        <li><strong><span class=\"kw-def\">SPST interentreprises</span></strong> : services communs à <span class=\"kw-clinique\">plusieurs entreprises</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Équipe pluridisciplinaire</h4>\n      <p>Le SPST s’organise en <span class=\"kw-def\">équipes pluridisciplinaires</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Médecin du travail</span></strong> : spécialiste du lien <span class=\"kw-clinique\">santé-travail</span> ; il <span class=\"kw-clinique\">anime et coordonne</span> l’équipe.</li>\n        <li><span class=\"kw-clinique\">Infirmiers</span> de santé au travail.</li>\n        <li><span class=\"kw-clinique\">Spécialistes des risques professionnels</span> : <span class=\"kw-etio\">ergonomes</span>, <span class=\"kw-etio\">ingénieurs</span>, <span class=\"kw-etio\">psychologues</span>…</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Secret professionnel du médecin du travail</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Secret de fabrication</span></strong> (= secret industriel).</li>\n        <li><strong><span class=\"kw-def\">Secret médical</span></strong> : le <span class=\"kw-clinique\">médecin traitant</span> et le <span class=\"kw-clinique\">médecin du travail</span> ne peuvent échanger des informations <span class=\"kw-alerte\">que par l’intermédiaire du patient</span> — le médecin du travail n’est pas considéré comme participant aux soins.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>À retenir.</strong> Le SPST est <span class=\"kw-alerte\">obligatoire dès le premier salarié</span> ; le médecin du travail <span class=\"kw-alerte\">n’échange jamais en direct</span> avec le médecin traitant — le patient fait le lien.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 182 — Environnement professionnel, sécurité au travail · 184 — Accident - maladie professionnel</em></p>","frequence":1},{"id":"183-2","rang":"B","rubrique":"Définition","titre":"Connaître les modes d’action des services de santé au travail","contenu":"<p>Le SPST agit selon <strong><span class=\"kw-def\">deux modes d’action</span></strong> complémentaires : une action <strong>sur le milieu de travail</strong> et un <strong><span class=\"kw-def\">suivi</span> de santé</strong> des travailleurs.</p>\n\n      <h4 class=\"kw-def\">1. Action sur le <span class=\"kw-def\">terrain</span> (milieu de travail)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Évaluer les risques professionnels</span>, au besoin par des <span class=\"kw-bio\">analyses</span> ou <span class=\"kw-bio\">mesures</span> (ex. <span class=\"kw-etio\">bruit</span>, <span class=\"kw-etio\">substances chimiques</span> dans des prélèvements atmosphériques).</li>\n        <li>Le médecin du travail a pour cela <span class=\"kw-clinique\">accès à la nature et à la composition des produits chimiques</span> utilisés et à leurs modalités d’emploi.</li>\n        <li><span class=\"kw-clinique\">Conseiller sur l’organisation des secours</span> et des services d’<span class=\"kw-alerte\">urgence</span>.</li>\n        <li>Mener des actions de <span class=\"kw-clinique\">promotion de la santé</span>.</li>\n        <li><span class=\"kw-clinique\">Conseiller l’employeur</span> sur la <span class=\"kw-ttt\">réduction</span> des risques professionnels constatés.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">2. <span class=\"kw-def\">Suivi</span> de santé</h4>\n      <ul>\n        <li>Le salarié peut rencontrer son médecin du travail <span class=\"kw-clinique\">à n’importe quel moment</span> ; certaines visites ont toutefois un calendrier réglementé.</li>\n        <li>Le médecin du travail <strong>décide des <span class=\"kw-def\">modalités du suivi individuel</span></strong> (contenu, périodicité), selon les <span class=\"kw-etio\">risques professionnels</span> mais aussi les <span class=\"kw-etio\">pathologies</span> ou le <span class=\"kw-etio\">terrain</span> (ex. <span class=\"kw-ci\">grossesse</span>).</li>\n        <li>Au terme de la consultation, il peut : <span class=\"kw-clinique\">conseiller/informer</span> le salarié, formuler des <span class=\"kw-clinique\">préconisations à l’employeur</span> (par écrit, dans le respect du secret médical), ou déclarer le salarié <span class=\"kw-alerte\">inapte à son poste</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Préconisations.</strong> L’employeur est tenu de <span class=\"kw-alerte\">prendre en considération</span> les propositions du médecin du travail et, en cas de refus, d’en <span class=\"kw-alerte\">faire connaître les motifs</span>. Le détail des visites est traité à l’objectif « <span class=\"kw-def\">suivi</span> de santé ».</div>","frequence":0},{"id":"183-3","rang":"B","rubrique":"Définition","titre":"Connaître les outils du médecin du travail et composition de l’équipe pluridisciplinaire","contenu":"<h4 class=\"kw-def\">Composition de l’équipe pluridisciplinaire</h4>\n      <p>L’équipe est <span class=\"kw-clinique\">animée et coordonnée</span> par le <strong><span class=\"kw-def\">médecin du travail</span></strong> et associe :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Infirmiers</span> de santé au travail (peuvent réaliser certaines visites par délégation).</li>\n        <li><strong><span class=\"kw-clinique\">Spécialistes des risques professionnels</span></strong> : <span class=\"kw-etio\">ergonomes</span>, <span class=\"kw-etio\">ingénieurs</span>, <span class=\"kw-etio\">psychologues</span>…</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Outils du médecin du travail</h4>\n      <ul>\n        <li><strong>Accès aux produits</strong> : nature et <span class=\"kw-clinique\">composition des produits chimiques</span> utilisés et leurs <span class=\"kw-clinique\">modalités d’emploi</span>.</li>\n        <li><strong><span class=\"kw-bio\">Fiches de données de sécurité</span> (FDS)</strong> : élaborées par les <span class=\"kw-etio\">fabricants</span>, transmises aux entreprises ; base de la connaissance des <span class=\"kw-etio\">risques chimiques</span>.</li>\n        <li><strong>Mesures et analyses sur le milieu</strong> : <span class=\"kw-bio\">métrologie d’ambiance</span> (<span class=\"kw-bio\">mesures atmosphériques</span> d’un composé chimique, <span class=\"kw-bio\">niveaux sonores</span> d’un atelier bruyant) et <span class=\"kw-bio\">mesures individuelles</span>.</li>\n        <li><strong><span class=\"kw-bio\">Indicateurs biologiques d’exposition</span></strong> : <span class=\"kw-bio\">toxiques ou métabolites</span> mesurés dans les <span class=\"kw-bio\">milieux biologiques</span> des sujets exposés.</li>\n        <li><strong><span class=\"kw-clinique\">Études ergonomiques</span></strong> des <span class=\"kw-clinique\">postes de travail</span>.</li>\n        <li><strong>Documents</strong> : <span class=\"kw-def\">DMST</span>, <span class=\"kw-def\">fiche d’entreprise</span>, <span class=\"kw-def\">fiche d’aptitude/inaptitude</span> (détaillés à l’objectif dédié).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">ℹ️ Les <span class=\"kw-bio\">FDS</span> sont l’outil central de l’identification des dangers chimiques : connaître leur origine (fabricants) est un point d’annale.</div>","frequence":0},{"id":"183-4","rang":"A","rubrique":"Définition","titre":"Connaître les principes de suivi de santé en santé au travail","contenu":"<p>Le médecin du travail <strong>décide des <span class=\"kw-def\">modalités du suivi individuel</span> de l’état de santé</strong> (contenu, périodicité), en fonction des <span class=\"kw-etio\">risques professionnels</span>, des <span class=\"kw-etio\">pathologies</span> et du <span class=\"kw-etio\">terrain</span> (ex. <span class=\"kw-ci\">grossesse</span>). Deux régimes de <span class=\"kw-def\">suivi</span> coexistent selon le poste.</p>\n\n      <h4 class=\"kw-def\">Deux régimes de <span class=\"kw-def\">suivi</span></h4>\n      <table >\n        <thead><tr><th>Régime</th><th>Pour qui ?</th><th>Périodicité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Suivi individuel renforcé</span> (SIR)</strong></td>\n            <td>Postes à risque pour leur <span class=\"kw-clinique\">santé</span> (agents <span class=\"kw-etio\">cancérogènes</span> / <span class=\"kw-etio\">toxiques pour la reproduction</span>, certains <span class=\"kw-etio\">risques biologiques</span>), pour leur <span class=\"kw-clinique\">sécurité</span> (ex. montage d’échafaudages) ou pour la <span class=\"kw-clinique\">sécurité de leurs collègues</span><br><em>Hors référentiel (abrégé) : âge <span class=\"kw-chiffre\">&lt; 18 ans</span>, femme enceinte, travailleur handicapé</em></td>\n            <td>Examen médical d’aptitude <strong>avant l’embauche</strong> (par le médecin du travail) ; <span class=\"kw-def\">suivi</span> périodique <span class=\"kw-chiffre\">≥ 1 fois / 4 ans</span> ; visites intermédiaires possibles (médecin ou infirmier)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Visite d’information et de prévention</span> (VIP)</strong></td>\n            <td>Salariés <span class=\"kw-clinique\">hors poste à risque</span></td>\n            <td>VIP <strong>à l’embauche</strong> ; puis périodique <span class=\"kw-chiffre\">≥ tous les 5 ans</span> (<span class=\"kw-chiffre\">≤ 3 ans</span> pour travailleurs handicapés, titulaires d’une pension d’invalidité, travailleurs de nuit) ; peut être <span class=\"kw-clinique\">déléguée à un infirmier</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Les différentes visites</h4>\n      <table >\n        <thead><tr><th>Visite</th><th>Modalités à connaître</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Embauche</strong></td><td>VIP ou examen d’aptitude (si SIR) à l’embauche.</td></tr>\n          <tr><td><strong>Périodique</strong></td><td><span class=\"kw-chiffre\">≥ 1 fois / 4 ans</span> en <span class=\"kw-def\">suivi</span> renforcé ; <span class=\"kw-chiffre\">≥ 1 fois / 5 ans</span> pour la VIP.</td></tr>\n          <tr><td><strong>Occasionnelle</strong></td><td>À l’initiative du médecin du travail, de l’employeur ou du salarié.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Pré-reprise</span></strong></td><td>Possible pendant un arrêt de travail <span class=\"kw-chiffre\">&gt; 1 mois</span> (ou plus court) pour préparer la reprise ; <span class=\"kw-alerte\">ne donne pas lieu à un avis d’aptitude</span> ❌.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Reprise</span></strong></td><td><span class=\"kw-alerte\">Obligatoire après un arrêt &gt; <span class=\"kw-chiffre\">60 jours</span></span> (et après congé maternité / maladie professionnelle) ; organisée par l’employeur dans les <span class=\"kw-chiffre\">&lt; 8 jours</span> suivant la reprise ; permet de <span class=\"kw-clinique\">se prononcer sur l’aptitude</span> au poste.</td></tr>\n          <tr><td><strong>Mi-carrière</strong></td><td>Proposée vers <span class=\"kw-chiffre\">45 ans</span> pour <span class=\"kw-clinique\">anticiper une désinsertion professionnelle</span> (âge, pénibilités, maladie chronique).</td></tr>\n          <tr><td><strong>Fin de carrière</strong></td><td>Visite de fin d’exposition à des risques particuliers (ex. chimiques) → <span class=\"kw-clinique\">suivi post-professionnel</span> en lien avec le <span class=\"kw-clinique\">médecin-conseil</span> et le <span class=\"kw-clinique\">médecin traitant</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">⚠️ <strong>Piège majeur (tombable).</strong> La visite de <span class=\"kw-alerte\">pré-reprise ne conclut jamais sur l’aptitude</span> ; c’est la visite de <span class=\"kw-alerte\">reprise</span> (arrêt <span class=\"kw-chiffre\">&gt; 60 jours</span>, dans les <span class=\"kw-chiffre\">&lt; 8 jours</span>) qui statue sur l’aptitude au poste.</div>","frequence":2},{"id":"183-5","rang":"B","rubrique":"Définition","titre":"Connaître les documents rédigés par le médecin du travail","contenu":"<table >\n        <thead><tr><th>Document</th><th>Contenu / règles</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Dossier médical en santé au travail</span> (DMST)</strong></td>\n            <td>\n              <strong>Création :</strong> à la <span class=\"kw-clinique\">1ʳᵉ visite d’information et de prévention</span>, pour chaque <span class=\"kw-clinique\">travailleur</span><br>\n              <strong>Contenu :</strong> <span class=\"kw-clinique\">état de santé</span> du travailleur ; <span class=\"kw-etio\">expositions</span> subies → apprécie le <span class=\"kw-clinique\">lien santé-expositions</span> ; <span class=\"kw-clinique\">avis et propositions</span> du médecin du travail<br>\n              <strong>DMP :</strong> un volet <span class=\"kw-clinique\">santé-travail</span> est intégré au <span class=\"kw-def\">dossier médical partagé</span>, accessible au médecin du travail <span class=\"kw-clinique\">avec l’autorisation du salarié</span><br>\n              <strong>Transmission :</strong> communiqué <span class=\"kw-alerte\">uniquement au médecin choisi par le patient</span>, à sa demande ; transmissible à un autre médecin du travail <span class=\"kw-clinique\">sauf opposition du travailleur</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Fiche d’entreprise</span></strong></td>\n            <td>Établie et mise à jour par le médecin du travail ; consigne les <span class=\"kw-etio\">risques professionnels</span> (avis sur les <span class=\"kw-etio\">dangers</span> / contraintes d’organisation) et les <span class=\"kw-clinique\">préconisations</span> pour <span class=\"kw-clinique\">réduire l’exposition</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Fiche d’aptitude</span></strong></td>\n            <td><strong>Pour qui ?</strong> <span class=\"kw-alerte\">uniquement les salariés exposés à des risques particuliers</span><br><strong>Transmise à qui ?</strong> à l’employeur, <span class=\"kw-alerte\">sans information sur la pathologie</span> du salarié ❌<br>Éventuellement assortie de <span class=\"kw-clinique\">préconisations d’adaptation du poste</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Fiche d’inaptitude</span></strong></td>\n            <td>Impose à l’employeur de <span class=\"kw-clinique\">chercher un autre poste</span> adapté aux capacités restantes ; à défaut de poste compatible → <span class=\"kw-alerte\">licenciement pour inaptitude médicale</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Confidentialité.</strong> La fiche d’aptitude transmise à l’employeur <span class=\"kw-alerte\">ne mentionne jamais la pathologie</span> ; le DMST ne se communique qu’au médecin choisi par le patient.</div>","frequence":0},{"id":"183-6","rang":"A","rubrique":"Définition","titre":"Connaître les principes des différents niveaux de prévention médicale et technique (primaire, secondaire, tertiaire)","contenu":"<p>L’action du médecin du travail est axée sur la <span class=\"kw-def\">prévention</span>, déclinée en <strong>trois niveaux</strong>, à la fois <span class=\"kw-clinique\">techniques</span> et <span class=\"kw-clinique\">médicaux</span>.</p>\n\n      <table >\n        <thead><tr><th>Niveau</th><th>Principe</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Primaire</span></strong></td>\n            <td>Repose sur l’<span class=\"kw-clinique\">évaluation des risques</span> puis la <span class=\"kw-clinique\">prévention technique</span> : mise en place ou amélioration des <strong>protections collectives et individuelles</strong> (avant toute atteinte).</td>\n            <td>Réduire le <span class=\"kw-etio\">bruit</span> par le <span class=\"kw-clinique\">capotage des machines</span> (collective) ou le port de <span class=\"kw-clinique\">bouchons auditifs</span> (individuelle).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Secondaire</span></strong></td>\n            <td>Surtout <span class=\"kw-clinique\">médicale</span> : <span class=\"kw-def\">suivi</span> de santé périodique visant à <span class=\"kw-alerte\">dépister les effets délétères</span> liés à l’exposition — effets <span class=\"kw-clinique\">fonctionnels</span>, <span class=\"kw-clinique\">cliniques</span> (<span class=\"kw-bio\">audiométrie</span>, <span class=\"kw-bio\">EFR</span>), <span class=\"kw-clinique\">biologiques</span> (atteinte <span class=\"kw-bio\">rénale</span> ou <span class=\"kw-bio\">hépatique</span>).<br>Inclut l’intervention technique après un <span class=\"kw-etio\">accident de travail</span> ou la découverte d’une <span class=\"kw-etio\">pathologie professionnelle</span>.</td>\n            <td><span class=\"kw-clinique\">Somnolence</span> (travail de nuit), <span class=\"kw-clinique\">troubles de mémoire</span> (solvants).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Tertiaire</span></strong></td>\n            <td>Technique <em>et</em> médicale : permettre au salarié porteur d’une <span class=\"kw-clinique\">déficience</span> de <span class=\"kw-clinique\">garder ou retrouver un emploi</span> dans l’entreprise. Nécessite bilan médical, connaissance des compétences et <strong>aménagement du poste</strong>.</td>\n            <td><span class=\"kw-clinique\">Aménagement de poste de travail</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Repère.</strong> Primaire = <span class=\"kw-alerte\">avant</span> l’atteinte (technique) ; secondaire = <span class=\"kw-alerte\">dépistage</span> précoce (médical) ; tertiaire = <span class=\"kw-alerte\">maintien dans l’emploi</span> malgré la déficience.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 184 — Accident - maladie professionnel</em></p>","frequence":1},{"id":"183-7","rang":"B","rubrique":"Définition","titre":"Connaître la démarche d’évaluation des risques","contenu":"<p>La <strong><span class=\"kw-def\">démarche d’évaluation des risques professionnels</span></strong> est <span class=\"kw-alerte\">obligatoire</span> dans les entreprises. Elle est conduite <strong>sous la <span class=\"kw-clinique\">responsabilité de l’employeur</span></strong> ; le <span class=\"kw-clinique\">SPST peut y participer</span> et conseiller l’employeur. À partir de l’évaluation, un <span class=\"kw-clinique\">plan d’action</span> est défini pour <span class=\"kw-clinique\">diminuer les risques selon les priorités</span>.</p>\n\n      <h4 class=\"kw-def\">Trois étapes</h4>\n      <table >\n        <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Identification et caractérisation des dangers</strong></td><td>Exige une bonne <span class=\"kw-clinique\">connaissance des postes de travail</span> ; pour les <span class=\"kw-etio\">risques chimiques</span>, via les <span class=\"kw-bio\">fiches de données de sécurité</span> (FDS) des produits commerciaux.</td></tr>\n          <tr><td><strong>2. Évaluation de l’exposition</strong></td><td><span class=\"kw-bio\">Mesures d’ambiance et individuelles</span> (<span class=\"kw-bio\">niveaux sonores</span>, <span class=\"kw-bio\">mesures atmosphériques</span>) ; <span class=\"kw-bio\">indicateurs biologiques d’exposition</span> ; <span class=\"kw-clinique\">études ergonomiques</span> des postes.</td></tr>\n          <tr><td><strong>3. Estimation des risques encourus</strong></td><td>Comparaison entre expositions mesurées et <strong><span class=\"kw-def\">valeurs limites d’exposition</span> (VLE)</strong> — valeurs à ne pas dépasser, fondées sur des relations <span class=\"kw-bio\">dose-réponse</span> (agents chimiques, <span class=\"kw-etio\">amiante</span>, <span class=\"kw-etio\">bruit</span>, <span class=\"kw-etio\">rayonnements ionisants</span>).</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">ℹ️ L’évaluation des risques est <span class=\"kw-alerte\">obligatoire</span> et de la <span class=\"kw-alerte\">responsabilité de l’employeur</span> — le SPST conseille, mais ne porte pas la responsabilité.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 182 — Environnement professionnel, sécurité au travail</em></p>","frequence":0},{"id":"183-8","rang":"A","rubrique":"Définition","titre":"Connaître la démarche de gestion des risques","contenu":"<p>La <strong><span class=\"kw-def\">gestion des risques</span></strong> suit toujours le <strong>même ordre hiérarchique</strong> : la <span class=\"kw-clinique\">faisabilité de chaque étape est évaluée avant de passer à la suivante</span> (si l’étape 1 est impossible, on passe à la 2, etc.).</p>\n\n      <h4 class=\"kw-def\">Hiérarchie des mesures (ordre fixe)</h4>\n      <table >\n        <thead><tr><th>Étape</th><th>Mesure</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Suppression des dangers</strong></td><td>Élimination ou modification des situations dangereuses : <span class=\"kw-clinique\">aménagement des locaux</span> et voies de circulation, <span class=\"kw-clinique\">changement du procédé</span> de travail.</td></tr>\n          <tr><td><strong>2. Limitation des émissions à la source</strong></td><td><strong>Protection collective</strong> : travail <span class=\"kw-clinique\">en vase clos</span>, <span class=\"kw-clinique\">aspiration</span> / hotte aspirante (solvants), <span class=\"kw-clinique\">capotage</span> d’une machine bruyante, <span class=\"kw-clinique\">chambre à pression négative</span> (patient tuberculeux).</td></tr>\n          <tr><td><strong>3. Limitation de l’exposition des salariés</strong></td><td><strong><span class=\"kw-def\">Équipements de protection individuelle</span> (EPI)</strong> adaptés : <span class=\"kw-clinique\">gants</span>, <span class=\"kw-clinique\">masques respiratoires</span>, <span class=\"kw-clinique\">lunettes</span>, <span class=\"kw-clinique\">casques anti-bruit</span>.</td></tr>\n          <tr><td><strong>4. Évaluation de l’efficacité</strong></td><td><span class=\"kw-def\">Surveillance</span> des niveaux d’exposition par <span class=\"kw-bio\">métrologie d’ambiance</span> (atmosphérique, sonore) ; <span class=\"kw-bio\">surveillance biologique</span> des expositions (solvants urinaires, <span class=\"kw-bio\">plombémie</span>).</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">⚠️ <strong>Logique « STOP ».</strong> On privilégie toujours la <span class=\"kw-alerte\">suppression</span> > la <span class=\"kw-alerte\">protection collective</span> (à la source) > la <span class=\"kw-alerte\">protection individuelle</span> (EPI). L’EPI est le <span class=\"kw-alerte\">dernier recours</span>, jamais la première réponse.</div>\n\n      <div class=\"callout callout-info\">✅ Le <strong><span class=\"kw-def\">suivi de santé</span></strong> permet de <span class=\"kw-clinique\">dépister les conséquences des expositions qui n’ont pu être supprimées</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 182 — Environnement professionnel, sécurité au travail · 184 — Accident - maladie professionnel</em></p>","frequence":1}],"astuces":[],"strategie":{},"cards":[{"i":"23d7456fa73c","n":183,"o":"183-4","u":"Définition","t":"Connaître les principes de suivi de santé en santé au travail","q":"Quelles sont les différentes visites possibles en santé au travail et leurs spécificités ?","a":"<ul><li><strong>Visite d'embauche</strong> : VIP ou examen d'aptitude (pour le SIR).</li><li><strong>Visite périodique</strong> : ≥ 1 fois / 4 ans en suivi renforcé ; ≥ 1 fois / 5 ans pour la VIP.</li><li><strong>Visite occasionnelle</strong> : à l'initiative du médecin du travail, de l'employeur ou du salarié.</li><li><strong>Visite de pré-reprise</strong> : possible pendant un arrêt de travail <strong>> 1 mois</strong> (ou plus court), pour préparer la reprise. Elle ne donne <strong>jamais lieu à un avis d'aptitude</strong>.</li><li><strong>Visite de reprise</strong> : obligatoire après un arrêt <strong>> 60 jours</strong>, congé maternité ou maladie professionnelle. Organisée par l'employeur dans les <strong>8 jours suivant la reprise</strong>, elle permet de se prononcer sur l'aptitude.</li><li><strong>Visite de mi-carrière</strong> : proposée vers <strong>45 ans</strong> pour anticiper la désinsertion professionnelle.</li><li><strong>Visite de fin de carrière</strong> : pour les salariés exposés à des risques particuliers, elle peut donner lieu à un suivi post-professionnel.</li></ul>"},{"i":"83fadbbc5a66","n":183,"o":"183-4","u":"Définition","t":"Connaître les principes de suivi de santé en santé au travail","q":"Quel est le piège classique concernant la distinction entre visite de pré-reprise et visite de reprise en médecine du travail ?","a":"<p>Le piège majeur est que la <strong>visite de pré-reprise</strong> (effectuée pendant un arrêt de travail) ne conclut <strong>jamais sur l'aptitude</strong>. C'est uniquement la <strong>visite de reprise</strong> (obligatoire après un arrêt de <strong>plus de 60 jours</strong>, organisée dans les <strong>8 jours</strong> suivant la reprise) qui statue sur l'aptitude au poste.</p>"},{"i":"8b95388eb761","n":183,"o":"183-4","u":"Définition","t":"Connaître les principes de suivi de santé en santé au travail","q":"Quels sont les deux régimes de suivi de santé en santé au travail et leurs caractéristiques principales ?","a":"<ul><li>Le <strong>Suivi Individuel Renforcé (SIR)</strong> concerne les salariés exposés à des <strong>risques pour leur santé</strong> (agents cancérogènes, toxiques pour la reproduction, risques biologiques), pour leur <strong>sécurité</strong> (montage d'échafaudages) ou pour la <strong>sécurité de leurs collègues</strong>. Il comprend un examen médical d'aptitude avant l'embauche par le médecin du travail et un suivi périodique <strong>au moins 1 fois tous les 4 ans</strong>.</li><li>La <strong>Visite d'Information et de Prévention (VIP)</strong> concerne les salariés hors poste à risque. Elle inclut une VIP à l'embauche, puis un suivi périodique <strong>au moins tous les 5 ans</strong> (ou tous les 3 ans pour les travailleurs handicapés, titulaires d'une pension d'invalidité, travailleurs de nuit).</li></ul>"},{"i":"d74dcf8f8910","n":183,"o":"183-4","u":"Définition","t":"Connaître les principes de suivi de santé en santé au travail","q":"Qui décide des modalités du suivi individuel de l'état de santé en santé au travail et selon quels critères ?","a":"<p>C'est le <strong>médecin du travail</strong> qui décide des modalités du suivi individuel de l'état de santé (contenu, périodicité). Il le fait en fonction des <strong>risques professionnels</strong> liés au poste, des <strong>pathologies</strong> du salarié et de son <strong>terrain</strong> (par exemple, la grossesse).</p>"},{"i":"1a357e3097aa","n":183,"o":"183-6","u":"Définition","t":"Connaître les principes des différents niveaux de prévention médicale et technique (primaire, secondaire, tertiaire)","q":"Quelle est la définition de la prévention tertiaire en médecine du travail et quels en sont ses principes ?","a":"<p>La prévention tertiaire en médecine du travail vise à <strong>maintenir dans l'emploi</strong> un salarié porteur d'une déficience ou à lui permettre de retrouver un emploi dans l'entreprise. Elle est à la fois <strong>technique et médicale</strong>.</p><p>Ses principes incluent :</p><ul><li>La réalisation d'un <strong>bilan médical</strong> approfondi.</li><li>La connaissance des <strong>compétences</strong> du salarié.</li><li>L'<strong>aménagement du poste de travail</strong> pour l'adapter aux capacités du salarié (ex: modification ergonomique du poste).</li></ul>"},{"i":"892206b39d37","n":183,"o":"183-6","u":"Définition","t":"Connaître les principes des différents niveaux de prévention médicale et technique (primaire, secondaire, tertiaire)","q":"Quelle est la définition de la prévention primaire en médecine du travail et quels en sont ses principes ?","a":"<p>La prévention primaire en médecine du travail correspond aux actions mises en place <strong>avant toute atteinte</strong> pour évaluer et réduire les risques professionnels. Elle repose sur la <strong>prévention technique</strong>.</p><p>Ses principes incluent :</p><ul><li>L'<strong>évaluation des risques</strong>.</li><li>La mise en place ou l'amélioration des <strong>protections collectives</strong> (ex: capotage des machines pour réduire le bruit).</li><li>La mise en place ou l'amélioration des <strong>protections individuelles</strong> (ex: port de bouchons auditifs).</li></ul>"},{"i":"f4c78342d078","n":183,"o":"183-6","u":"Définition","t":"Connaître les principes des différents niveaux de prévention médicale et technique (primaire, secondaire, tertiaire)","q":"Quelle est la définition de la prévention secondaire en médecine du travail et quels en sont ses principes ?","a":"<p>La prévention secondaire en médecine du travail vise le <strong>dépistage précoce</strong> des effets délétères liés à l'exposition professionnelle. Elle est principalement <strong>médicale</strong>.</p><p>Ses principes incluent :</p><ul><li>Le <strong>suivi de santé périodique</strong> (visites médicales régulières).</li><li>La réalisation d'examens fonctionnels et cliniques (ex: <strong>audiométrie</strong>, <strong>EFR</strong>) ou biologiques (recherche d'atteinte rénale ou hépatique).</li><li>L'intervention technique après un <strong>accident de travail</strong> ou la découverte d'une <strong>pathologie professionnelle</strong>.</li></ul>"},{"i":"2aaa08b0ebdb","n":183,"o":"183-8","u":"Définition","t":"Connaître la démarche de gestion des risques","q":"Comment évalue-t-on l'efficacité des mesures de gestion des risques en santé au travail ?","a":"<p>L'efficacité des mesures de gestion des risques est évaluée par la <strong>surveillance des niveaux d'exposition</strong> (par métrologie d'ambiance comme pour l'air ou le bruit) et par la <strong>surveillance biologique des expositions</strong> (comme la recherche de solvants urinaires ou la plombémie). Le suivi de santé permet également de dépister les conséquences des expositions qui n'ont pu être supprimées.</p>"},{"i":"8f711b05c5fb","n":183,"o":"183-8","u":"Définition","t":"Connaître la démarche de gestion des risques","q":"Quelle est la première étape dans la hiérarchie des mesures de gestion des risques en santé au travail ?","a":"<p>La première étape est la <strong>suppression des dangers</strong>. Elle consiste à <strong>éliminer</strong> ou à <strong>modifier</strong> les situations dangereuses, par exemple par l'aménagement des locaux ou le changement des procédés de travail.</p>"},{"i":"ae81bff4ce65","n":183,"o":"183-8","u":"Définition","t":"Connaître la démarche de gestion des risques","q":"Selon la hiérarchie des mesures de gestion des risques, à quel niveau se situent les Équipements de Protection Individuelle (EPI) ?","a":"<p>Les Équipements de Protection Individuelle (EPI) se situent en <strong>troisième position</strong> dans la hiérarchie des mesures. Ils constituent une mesure de <strong>limitation de l'exposition des salariés</strong>, mais ne doivent être considérés qu'après la suppression des dangers et la protection collective à la source. C'est le <strong>dernier recours</strong>, jamais la première réponse.</p>"},{"i":"b4addeeec087","n":183,"o":"183-8","u":"Définition","t":"Connaître la démarche de gestion des risques","q":"Après la suppression des dangers, quelle est l'étape suivante dans la gestion des risques et quels en sont des exemples ?","a":"<p>La deuxième étape est la <strong>limitation des émissions à la source</strong> par des mesures de <strong>protection collective</strong>. Des exemples incluent le travail en vase clos, l'aspiration ou les hottes aspirantes pour les solvants, le capotage d'une machine bruyante, ou encore l'utilisation de chambres à pression négative.</p>"}]};